    const plansRef = ref([]);
    const dialogVisible = ref(false);
    const selectedPlan = ref(null);
    const logsRef = ref([]); // 🆕 存储实时日志

    const fetchPlans = async () => {
      try {
        const response = await axios.get('http://localhost:8081/plan/list');
        plansRef.value = response.data.records || [];
      } catch (error) {
        ElMessage.error('获取计划数据失败');
        console.error(error);
      }
    };
    const refreshPlans = () => {
      fetchPlans();
    };
    let intervalId = null;
    onMounted(() => {
      intervalId = setInterval(() => {
        refreshPlans();
      }, 1000);
    });
    onBeforeUnmount(() => {
      if (intervalId) {
        clearInterval(intervalId);
      }
      closeSocket();
    });
    const viewPlan = plan => {
      selectedPlan.value = plan;
      dialogVisible.value = true;
    };

    // --- WebSocket 相关 ---
    let socket = null;
    const openSocket = () => {
      if (socket) return; // 防止重复打开
      socket = new WebSocket('ws://localhost:8081/ws/log');
      socket.onopen = () => {
        console.log('WebSocket连接已打开');
        logsRef.value.push('[系统] WebSocket连接已建立');
      };
      socket.onmessage = event => {
        console.log('收到消息:', event.data);
        logsRef.value.push(event.data);
      };
      socket.onclose = () => {
        console.log('WebSocket连接已关闭');
        logsRef.value.push('[系统] WebSocket连接已关闭');
        socket = null;
      };
      socket.onerror = error => {
        console.error('WebSocket出错:', error);
        logsRef.value.push('[系统] WebSocket发生错误');
      };
    };
    const closeSocket = () => {
      if (socket) {
        socket.close();
        socket = null;
      }
    };
    // --- WebSocket 相关 ---

    const executePlan = async plan => {
      try {
        let url = '';
        let params = {};
        switch (plan.type) {
          case 'HTTP':
            url = 'http://localhost:8081/test/http';
            params = {
              container1: plan.container1,
              container2Ip: plan.container2Ip
            };
            break;
          case 'TCP':
            url = 'http://localhost:8081/test/tcp';
            params = {
              container1: plan.container1,
              container2: plan.container2,
              container2Ip: plan.container2Ip,
              size: plan.size,
              time: plan.time
            };
            break;
          case 'UDP':
            url = 'http://localhost:8081/test/udp';
            params = {
              container1: plan.container1,
              container2: plan.container2,
              container2Ip: plan.container2Ip,
              velocity: plan.velocity,
              size: plan.size
            };
            break;
          case 'NETCAT':
            url = 'http://localhost:8081/test/netcat';
            params = {
              container1: plan.container1,
              container2Ip: plan.container2Ip
            };
            break;
          case 'PING':
            url = 'http://localhost:8081/test/ping';
            params = {
              container1: plan.container1,
              container2Ip: plan.container2Ip,
              size: plan.size,
              num: plan.num
            };
            break;
          default:
            ElMessage.warning(`未知的测试类型: ${plan.type}`);
            return;
        }

        // 每次执行，清空旧日志，打开socket监听
        logsRef.value = [];
        openSocket();
        const response = await axios.post(url, null, {
          params: params
        });
        ElMessage.success(`执行指令已发送：${response.data}`);
      } catch (error) {
        ElMessage.error(`执行失败：${error.message ?? error}`);
        console.error(error);
      }
    };
    const deletePlan = async plan => {
      try {
        await ElMessageBox.confirm(`确定要删除计划「${plan.name}」吗？`, '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        });
        await axios.delete(`http://localhost:8081/plan/delete/${plan.id}`);
        ElMessage.success(`已删除计划: ${plan.name}`);
        refreshPlans();
      } catch (error) {
        if (error !== 'cancel') {
          ElMessage.error('删除失败');
          console.error(error);
        }
      }
    };
    const __returned__ = {
      plansRef,
      dialogVisible,
      selectedPlan,
      logsRef,
      fetchPlans,
      refreshPlans,
      get intervalId() {
        return intervalId;
      },
      set intervalId(v) {
        intervalId = v;
      },
      viewPlan,
      get socket() {
        return socket;
      },
      set socket(v) {
        socket = v;
      },
      openSocket,
      closeSocket,
      executePlan,
      deletePlan,
      ref,
      onMounted,
      onBeforeUnmount,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      get ElMessageBox() {
        return ElMessageBox;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
